def count_triples(S, n, coloring_type):
    """
    Counts the number of ordered triples (x, y, z) from S^3 such that
    x+y+z is divisible by n, given a specific coloring.

    Args:
        S (int): The size of the set {1, 2, ..., n}.
        n (int): The modulus.
        coloring_type (str): 'all_red' or 'alternating'.

    Returns:
        dict: A dictionary containing C_RRR and C_BBB counts.
    """
    S_set = set(range(1, n + 1))
    R = set()
    B = set()

    if coloring_type == 'all_red':
        R = S_set
        B = set()
    elif coloring_type == 'alternating':
        # Red if odd, Blue if even
        R = {i for i in S_set if i % 2 != 0}
        B = {i for i in S_set if i % 2 == 0}
    else:
        raise ValueError("Invalid coloring type")

    C_RRR = 0
    C_BBB = 0

    # Count RRR triples
    for x in R:
        for y in R:
            for z in R:
                if (x + y + z) % n == 0:
                    C_RRR += 1

    # Count BBB triples
    for x in B:
        for y in B:
            for z in B:
                if (x + y + z) % n == 0:
                    C_BBB += 1

    return {'C_RRR': C_RRR, 'C_BBB': C_BBB}

results = {}
for n in range(1, 11):
    results[n] = {}

    # 1. All Red Coloring
    counts_all_red = count_triples(n, n, 'all_red')
    results[n]['All_Red'] = counts_all_red['C_RRR'] # C_BBB is 0

    # 2. Alternating Colors
    counts_alternating = count_triples(n, n, 'alternating')
    total_alternating = counts_alternating['C_RRR'] + counts_alternating['C_BBB']
    results[n]['Alternating'] = total_alternating

# Print results in a structured format for easy logging
print("N | All_Red (C) | Alternating (C)")
print("-" * 40)
for n, data in results.items():
    print(f"{n:2} | {data['All_Red']:11} | {data['Alternating']:13}")

import math

primes = [47, 53, 59, 61, 67, 71, 73, 79, 83, 89]
results = {}

for p in primes:
    D = 24184 - 3 * p**2
    if D < 0:
        continue

    k = math.isqrt(D)
    if k * k == D:
        # D is a perfect square k^2

        # Check if 3p +/- k is divisible by 6
        r1_num = 3*p + k
        r2_num = 3*p - k

        r1_int = None
        if r1_num % 6 == 0:
            r1_int = r1_num // 6

        r2_int = None
        if r2_num % 6 == 0:
            r2_int = r2_num // 6

        results[p] = {'k': k, 'r1': r1_int, 'r2': r2_int}

print(results)

